<template>
  <AppLayout>
    <div class="space-y-6">
      <header><h1 class="text-2xl font-bold">{{ t('admin.bi.title') }}</h1><p class="mt-2 text-gray-500">{{ t('biNative.metadataOnly') }}</p></header>
      <nav class="flex flex-wrap gap-2" aria-label="BI"><button v-for="item in tabs" :key="item" class="btn" :class="tab === item ? 'btn-primary' : 'btn-secondary'" :aria-pressed="tab === item" @click="tab = item">{{ t(`biNative.${item}`) }}</button></nav>
      <section v-if="tab === 'overview'" class="card p-6 space-y-4" :aria-busy="overviewLoading">
        <p v-if="overviewError" role="alert">{{ overviewError }}</p><button class="btn btn-secondary" :disabled="overviewLoading" @click="loadOverview">{{ t('common.refresh') }}</button>
        <template v-if="overview"><h2>{{ overview.bi_enabled ? t('biNative.enabled') : t('biNative.disabled') }}</h2><p>{{ overview.privacy_notice_published ? t('biNative.privacyPublished') : t('biNative.privacyMissing') }}</p><router-link to="/admin/settings" class="btn btn-secondary">{{ t('biNative.configure') }}</router-link><dl class="grid gap-3 sm:grid-cols-3"><div v-for="(count, name) in overview.counts" :key="name"><dt>{{ t(`biNative.counts.${name}`) }}</dt><dd class="text-2xl font-medium">{{ count }}</dd></div></dl><dl v-if="overview.config" class="grid gap-3 sm:grid-cols-2"><div v-for="(value, key) in overview.config" :key="key"><dt>{{ key }}</dt><dd class="break-all">{{ value }}</dd></div></dl><p class="text-sm">Desktop: {{ overview.desktop_enabled ? t('common.enabled') : t('common.disabled') }}</p></template>
      </section>
      <section v-if="tab === 'onboarding' || tab === 'identities'" class="space-y-4">
        <div class="card p-5"><h2 class="font-medium">{{ t('biNative.onboarding') }}</h2><p class="text-sm text-gray-500">{{ t('biNative.identityHint') }}</p><input v-model="search" class="input mt-3" :placeholder="t('common.search')" /><OperationsTable :rows="regions.organizations.rows" :columns="['name','status','reporting_enabled','summary_enabled','weekly_summary_enabled','monthly_summary_enabled','analysis_model','users','last_received_at']" :loading="regions.organizations.loading" :error="regions.organizations.error" @retry="load('organizations')"><template #actions="{ row }"><router-link class="btn btn-secondary" :to="organizationLink(String(row.id))">{{ t('biNative.openOrganization') }}</router-link><button class="btn btn-secondary" @click="selectedOrganization = String(row.id)">{{ t('biNative.invitations') }}</button></template></OperationsTable><More path="organizations" /></div>
        <BIGrantManagement v-if="selectedOrganization" :key="selectedOrganization" :organization-id="selectedOrganization" />
        <template v-if="tab === 'identities'"><div class="card p-5"><h2 class="font-medium">{{ t('biNative.users') }}</h2><OperationsTable :rows="regions['identities/users'].rows" :columns="['display_name','status','authorization_version','created_at','last_seen_at']" :loading="regions['identities/users'].loading" :error="regions['identities/users'].error" @retry="load('identities/users')"><template #actions="{ row }"><button class="btn btn-secondary" :disabled="busy" @click="setStatus(String(row.id), row.status === 'active' ? 'disabled' : 'active')">{{ t(row.status === 'active' ? 'biNative.disableUser' : 'biNative.enableUser') }}</button></template></OperationsTable><More path="identities/users" /></div><div class="card p-5"><h2>{{ t('biNative.sessions') }}</h2><OperationsTable :rows="regions['identities/sessions'].rows" :columns="['bi_user_id','status','client_version','last_seen_at','expires_at']" :loading="regions['identities/sessions'].loading" :error="regions['identities/sessions'].error" @retry="load('identities/sessions')" /><More path="identities/sessions" /></div></template>
      </section>
      <section v-if="tab === 'tasks'" class="space-y-4"><div class="card p-5"><h2>{{ t('biNative.tasks') }}</h2><select v-model="kind" class="input max-w-xs"><option value="">{{ t('common.all') }}</option><option v-for="k in ['day','week','month']" :key="k" :value="k">{{ t(`biNative.${k}`) }}</option></select><OperationsTable :rows="regions['report-tasks'].rows" :columns="['organization_name','kind','period_start','period_end','status','revision','available_sources','missing_sources','model','total_tokens','actual_cost','reason']" :loading="regions['report-tasks'].loading" :error="regions['report-tasks'].error" @retry="load('report-tasks')"><template #actions="{ row }"><router-link class="btn btn-secondary" :to="reportLink(row)">{{ t('biNative.openOrganization') }}</router-link></template></OperationsTable><More path="report-tasks" /></div><div class="card p-5"><h2>{{ t('biNative.executions') }}</h2><OperationsTable :rows="regions['report-executions'].rows" :columns="['organization_id','kind','period_start','revision','model','status','round','chunk','attempt','total_tokens','actual_cost','error','started_at']" :loading="regions['report-executions'].loading" :error="regions['report-executions'].error" @retry="load('report-executions')" /><More path="report-executions" /></div></section>
      <section v-if="tab === 'audit'" class="space-y-4"><div class="card p-5"><OperationsTable :rows="regions.audit.rows" :columns="['actor_type','actor_id','organization_id','action','target_id','request_id','created_at']" :loading="regions.audit.loading" :error="regions.audit.error" @retry="load('audit')" /><More path="audit" /></div><form class="card p-5 space-y-4" @submit.prevent="saveRetention"><h2>{{ t('biNative.retention') }}</h2><p>{{ t('biNative.scopeCleanup') }}</p><p v-if="retentionError" role="alert">{{ retentionError }}</p><button class="btn btn-secondary" type="button" @click="loadRetention">{{ t('common.refresh') }}</button><template v-if="policy"><label class="block">{{ t('biNative.auditDays') }}<input v-model.number="policy.audit_days" class="input max-w-xs" type="number" min="1" max="3650" required /></label><label class="block">{{ t('biNative.ephemeralDays') }}<input v-model.number="policy.ephemeral_days" class="input max-w-xs" type="number" min="1" max="365" required /></label><button class="btn btn-primary" :disabled="busy">{{ t('common.save') }}</button><button class="btn btn-secondary" type="button" :disabled="busy" @click="cleanup">{{ t('biNative.cleanup') }}</button></template></form></section>
      <TotpStepUpDialog :controller="stepUp" />
      <p v-if="actionError" role="alert" class="text-red-600">{{ actionError }}</p>
    </div>
  </AppLayout>
</template>
<script setup lang="ts">
import { defineComponent, h, onBeforeUnmount, reactive, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import AppLayout from '@/components/layout/AppLayout.vue'
import TotpStepUpDialog from '@/components/auth/TotpStepUpDialog.vue'
import { useStepUp, isStepUpCancelled } from '@/composables/useStepUp'
import BIGrantManagement from '@/components/bi/BIGrantManagement.vue'
import OperationsTable from '@/components/bi/OperationsTable.vue'
import api, { type BIOverview, type BIOperationRow, type BIRetentionPolicy } from '@/api/admin/bi'
const { t } = useI18n(), tabs = ['overview','onboarding','identities','tasks','audit'] as const
const tab = ref<typeof tabs[number]>('overview'), overview = ref<BIOverview>(), overviewLoading = ref(false), overviewError = ref(''), search = ref(''), kind = ref(''), selectedOrganization = ref(''), busy = ref(false), actionError = ref(''), policy = ref<BIRetentionPolicy>(), retentionError = ref('')
const stepUp = useStepUp()
const paths = ['organizations','identities/users','identities/sessions','report-tasks','report-executions','audit']
const regions = reactive<Record<string, { rows: BIOperationRow[]; page: number; more: boolean; loading: boolean; error: string; generation: number }>>(Object.fromEntries(paths.map(path => [path, { rows: [], page: 1, more: false, loading: false, error: '', generation: 0 }])))
let alive = true, searchTimer: ReturnType<typeof setTimeout> | undefined
const causeMessage = (cause: unknown) => t((cause as { status?: number }).status === 423 ? 'biNative.stepUp' : 'biNative.failed')
const organizationLink = (id: string, target = 'grants') => ({ path: `/admin/desktop/organizations/${encodeURIComponent(id)}`, query: { tab: target } })
const reportLink = (row: BIOperationRow) => ({path:`/admin/desktop/organizations/${encodeURIComponent(String(row.organization_id))}`,query:{tab:'reports',report_kind:String(row.kind),period_start:String(row.period_start),report_id:String(row.report_id??''),report_date:String(row.period_start)}})
async function loadOverview() { overviewLoading.value = true; overviewError.value = ''; try { const value = await api.getOverview(); if (alive) overview.value = value } catch (cause) { if (alive) overviewError.value = causeMessage(cause) } finally { if (alive) overviewLoading.value = false } }
async function load(path: string, page = 1) { const region = regions[path], g = ++region.generation; region.loading = true; region.error = ''; const params: Record<string,string> = {}; if (path === 'organizations') params.search = search.value; if (path.startsWith('report-')) params.kind = kind.value; try { const value = await api.list(path,page,params); if (!alive || g !== region.generation) return; region.rows = page === 1 ? value.items : [...region.rows,...value.items]; region.page = page; region.more = value.has_more } catch (cause) { if (alive && g === region.generation) region.error = causeMessage(cause) } finally { if (alive && g === region.generation) region.loading = false } }
const More = defineComponent({ props: { path: { type: String, required: true } }, setup(props) { return () => h('div', { class: 'flex gap-3 mt-3' }, [h('button', { class: 'btn btn-secondary', disabled: regions[props.path].loading, onClick: () => load(props.path) }, t('common.refresh')), regions[props.path].more ? h('button', { class: 'btn btn-secondary', disabled: regions[props.path].loading, onClick: () => load(props.path, regions[props.path].page + 1) }, t('bi.loadMore')) : null]) } })
async function setStatus(id: string, status: string) { if (!window.confirm(t(status === 'disabled' ? 'biNative.disableUser' : 'biNative.enableUser'))) return; busy.value = true; actionError.value = ''; try { await stepUp.run(() => api.userStatus(id,status)); void load('identities/users'); void load('identities/sessions'); void loadOverview() } catch (cause) { if (!isStepUpCancelled(cause)) actionError.value = causeMessage(cause) } finally { busy.value = false } }
async function loadRetention() { retentionError.value = ''; try { const value = await api.retention(); if (alive) policy.value = value } catch (cause) { if (alive) if (!isStepUpCancelled(cause)) retentionError.value = causeMessage(cause) } }
async function saveRetention() { if (!policy.value) return; busy.value = true; try { const input = { ...policy.value }; await stepUp.run(() => api.saveRetention(input)); await loadRetention() } catch (cause) { if (!isStepUpCancelled(cause)) retentionError.value = causeMessage(cause) } finally { busy.value = false } }
async function cleanup() { busy.value = true; try { await stepUp.run(() => api.cleanup()); void load('audit'); void loadOverview() } catch (cause) { if (!isStepUpCancelled(cause)) retentionError.value = causeMessage(cause) } finally { busy.value = false } }
watch(tab, value => { if (value === 'overview') void loadOverview(); if (['onboarding','identities'].includes(value)) void load('organizations'); if (value === 'identities') { void load('identities/users'); void load('identities/sessions') } if (value === 'tasks') { void load('report-tasks'); void load('report-executions') } if (value === 'audit') { void load('audit'); void loadRetention() } }, { immediate: true })
watch(search, () => { clearTimeout(searchTimer); regions.organizations.generation++; regions.organizations.rows = []; selectedOrganization.value = ''; searchTimer = setTimeout(() => { void load('organizations') },300) })
watch(kind, () => { for (const path of ['report-tasks','report-executions']) { regions[path].generation++; regions[path].rows = []; void load(path) } })
onBeforeUnmount(() => { alive = false; stepUp.onCancel(); clearTimeout(searchTimer) })
</script>
